module PackageVersions
  # Debian package version ordering (FR-2.4, P2-S09), ported from dpkg's lib/dpkg/parsehelp.c (parseversion)
  # and lib/dpkg/version.c (verrevcmp, dpkg_version_compare). The conformance corpus in
  # spec/fixtures/dpkg/compare-versions.tsv is generated by `dpkg --compare-versions` on Debian 13 and must
  # pass unchanged; script/dpkg-corpus.sh regenerates and checks it.
  #
  # A version is [epoch:]upstream[-revision]. Parsing follows dpkg exactly: what dpkg rejects with an error is
  # Invalid; what it only warns about (an upstream that does not start with a digit, an unusual character) is
  # compared as dpkg compares it. Two deliberate differences, both kept out of the corpus: an empty string is
  # Invalid (dpkg treats it as "no version"), and so is any non-ASCII byte (dpkg's order then depends on the
  # platform's signed char).
  module Dpkg
    Version = Data.define(:epoch, :upstream, :revision) do
      def to_s = "#{"#{epoch}:" if epoch.positive?}#{upstream}#{"-#{revision}" unless revision.empty?}"
    end

    EPOCH_MAX = 2**31 - 1 # INT_MAX, as dpkg
    WHITESPACE = " \t\n\v\f\r" # C isspace in the C locale

    MANAGER = "dpkg"

    module_function

    # A Version, or an Invalid with dpkg's reason. Never raises for a String; anything else is Invalid.
    def parse(text)
      return Invalid.new(version: text, reason: "version is not a string") unless text.is_a?(String)
      return Invalid.new(version: text, reason: "version string is empty") if text.empty?
      return Invalid.new(version: text, reason: "version string is not ASCII") unless text.ascii_only?

      string = text.sub(/\A[#{WHITESPACE}]+/o, "").sub(/[#{WHITESPACE}]+\z/o, "")
      return invalid(text, "version string is empty") if string.empty?
      return invalid(text, "version string has embedded spaces") if string.match?(/[#{WHITESPACE}]/o)

      epoch, rest = split_epoch(string)
      return invalid(text, epoch) if epoch.is_a?(String)
      return invalid(text, "nothing after colon in version number") if rest.empty?

      hyphen = rest.rindex("-")
      upstream = hyphen ? rest[0...hyphen] : rest
      revision = hyphen ? rest[(hyphen + 1)..] : ""
      return invalid(text, "revision number is empty") if hyphen && revision.empty?
      return invalid(text, "version number is empty") if upstream.empty?

      Version.new(epoch:, upstream:, revision:)
    end

    def valid?(text) = parse(text).is_a?(Version)

    # -1, 0, or 1 as dpkg --compare-versions would answer lt, eq, gt; :invalid when either side is Invalid.
    def compare(left, right)
      a = left.is_a?(Version) ? left : parse(left)
      b = right.is_a?(Version) ? right : parse(right)
      return :invalid unless a.is_a?(Version) && b.is_a?(Version)

      result = a.epoch <=> b.epoch
      result = verrevcmp(a.upstream, b.upstream) if result.zero?
      result = verrevcmp(a.revision, b.revision) if result.zero?
      result <=> 0
    end

    # [epoch, rest], or [reason, nil]. dpkg reads the epoch with strtol(base 10): an optional sign, digits.
    def split_epoch(string)
      colon = string.index(":")
      return [ 0, string ] unless colon

      digits = string[0...colon]
      return [ "epoch in version is empty", nil ] if digits.empty? || !digits.match?(/\A[+-]?\d/)
      return [ "epoch in version is not number", nil ] unless digits.match?(/\A[+-]?\d+\z/)

      epoch = Integer(digits, 10)
      return [ "epoch in version is negative", nil ] if epoch.negative?
      return [ "epoch in version is too big", nil ] if epoch > EPOCH_MAX

      [ epoch, string[(colon + 1)..] ]
    end

    # dpkg's verrevcmp: alternating runs of non-digits, compared by order(), and digits, compared numerically.
    def verrevcmp(a, b)
      a = a.bytes
      b = b.bytes
      i = j = 0
      while i < a.size || j < b.size
        first_diff = 0
        while (i < a.size && !digit?(a[i])) || (j < b.size && !digit?(b[j]))
          ac = order(a[i])
          bc = order(b[j])
          return ac - bc if ac != bc

          i += 1
          j += 1
        end
        i += 1 while i < a.size && a[i] == 48 # "0"
        j += 1 while j < b.size && b[j] == 48
        while i < a.size && j < b.size && digit?(a[i]) && digit?(b[j])
          first_diff = a[i] - b[j] if first_diff.zero?
          i += 1
          j += 1
        end
        return 1 if i < a.size && digit?(a[i])
        return -1 if j < b.size && digit?(b[j])
        return first_diff unless first_diff.zero?
      end
      0
    end

    # The end of the string sorts as 0, a tilde before it, letters by ASCII, and anything else after letters.
    def order(byte)
      return 0 if byte.nil? || digit?(byte)
      return byte if (65..90).cover?(byte) || (97..122).cover?(byte)
      return -1 if byte == 126 # "~"

      byte + 256
    end

    def digit?(byte) = byte && byte.between?(48, 57)

    def invalid(text, reason) = Invalid.new(version: text, reason:)

    private_class_method :split_epoch, :verrevcmp, :order, :digit?, :invalid
  end
end
